    <script>document.querySelectorAll('.report-tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.report-tab').forEach(x=>{x.classList.toggle('bg-slate-900',x===tab);x.classList.toggle('text-white',x===tab);x.classList.toggle('text-slate-600',x!==tab)});document.querySelectorAll('.report-panel').forEach(x=>x.classList.toggle('hidden',x.dataset.reportPanel!==tab.dataset.reportTab))}));</script>
